import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppList } from './app-list.entity';

@Injectable()
export class AppListService {
  public constructor(private readonly dataSource: DataSource) {}

  public async getMenu(): Promise<Array<AppList>> {
    const treeRepository = this.dataSource.getTreeRepository(AppList);

    const topLevelMenus = await treeRepository.findTrees({
      relations: ['pages'],
    });

    topLevelMenus.sort((a, b) => a.order - b.order);

    for (const menu of topLevelMenus) {
      menu.isClickable = menu.hasNoChildren();
    }

    return topLevelMenus;
  }

  public async getAppList(): Promise<Array<{ id: number; appName: string }>> {
    const appListRepository = this.dataSource.getRepository(AppList);

    const appLists = await appListRepository.find({
      select: ['id', 'appName'],
      order: { order: 'ASC' },
    });

    return appLists;
  }
}

