import MssqlConfigurationService from '@/config/database/mssql/abstract.mssql.config.service';

interface MssqlConfigurationObject {
  type: string;
  host: string | undefined;
  port: number;
  username: string | undefined;
  password: string | undefined;
  database: string | undefined;
  synchronize: boolean;
  managedIdentityClientId: string | undefined;
  entities: Array<string>;
  migrations: Array<string>;
  migrationsTableName: string;
  encrypt: boolean;
  migrationsWaitDelayMilliseconds: number;
  migrationsWaitRetryLimit: number;
}

export default class DefaultMssqlConfigurationService extends MssqlConfigurationService {
  constructor(private readonly mssqlConfig: MssqlConfigurationObject) {
    super();
  }

  get type(): string {
    return this.mssqlConfig.type ?? '';
  }

  get host(): string {
    return this.mssqlConfig.host ?? '';
  }

  get port(): number {
    return this.mssqlConfig.port ?? 1433;
  }

  get username(): string {
    return this.mssqlConfig.username ?? '';
  }

  get password(): string {
    return this.mssqlConfig.password ?? '';
  }

  get database(): string {
    return this.mssqlConfig.database ?? '';
  }

  get synchronize(): boolean {
    return this.mssqlConfig.synchronize ?? false;
  }

  get useManagedIdentity(): boolean {
    return this.managedIdentityClientId?.trim().length > 0;
  }

  get managedIdentityClientId(): string {
    return this.mssqlConfig.managedIdentityClientId ?? '';
  }

  get encrypt(): boolean {
    return this.mssqlConfig.encrypt ?? false;
  }

  get entities(): Array<string> {
    return this.mssqlConfig.entities ?? [];
  }

  get migrations(): Array<string> {
    return this.mssqlConfig.migrations ?? [];
  }

  get migrationsTableName(): string {
    return this.mssqlConfig.migrationsTableName ?? 'migrations_TypeORM';
  }

  get migrationsWaitDelayMilliseconds(): number {
