import * as fs from 'node:fs';
import path from 'node:path';
import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Permission } from '@/permission/permission.entity';
import { Role } from '@/role/role.entity';

interface ScreenRole {
  appName: string;
  roles: Array<string>;
}

@Injectable()
export class PermissionSeeder {
  private readonly screenRolesPath: string;

  public constructor(
    @InjectRepository(Role)
    private readonly roleRepository: Repository<Role>,
    @InjectRepository(Permission)
    private readonly permissionRepository: Repository<Permission>,
  ) {
    this.screenRolesPath = path.join(process.cwd(), 'data/screen-roles.json');
    fs.watchFile(this.screenRolesPath, async () => {
      await this.seed();
    });
  }

  public async seed(): Promise<void> {
    const screenRolesPath = path.join(process.cwd(), 'data/screen-roles.json');
    const screenRoles: Array<ScreenRole> = JSON.parse(
      fs.readFileSync(screenRolesPath, 'utf8'),
    );

    const existingPermissions = await this.permissionRepository.find({
      relations: ['role'],
    });

    const currentPermissionsSet = new Set<string>();

    for (const screen of screenRoles) {
      for (const roleName of screen.roles) {
        currentPermissionsSet.add(`${screen.appName}:${roleName}`);
      }
    }

    await Promise.all(
      existingPermissions.map(async (existingPermission) => {
        const permissionKey = `${existingPermission.appName}:${existingPermission.role.roleName}`;
        if (!currentPermissionsSet.has(permissionKey)) {
          await this.permissionRepository.remove(existingPermission);
        }
      }),
    );

    await Promise.all(
      screenRoles.map(async (screen) => {
        await Promise.all(
          screen.roles.map(async (roleName) => {
            const existingRole = await this.roleRepository.findOneBy({
              roleName,
            });
            if (existingRole) {
              const exists = await this.permissionExists(
                screen.appName,
                existingRole,
              );
              if (!exists) {
                const newPermission = new Permission();
                newPermission.appName = screen.appName;
                newPermission.role = existingRole;
                await this.permissionRepository.save(newPermission);
              }
            }
          }),
        );
      }),
    );
  }

  public async permissionExists(appName: string, role: Role): Promise<boolean> {
    const count = await this.permissionRepository.count({
      where: {
        appName,
        role,
      },
    });
    return count > 0;
  }
}

